CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"8db2245c-531f-5d93-82e7-5a778aed6363","source_id":"0064","name_en":"barbell one arm bent over row","name_ar":"\u0627\u0644\u062d\u062f\u064a\u062f \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0639\u0627\u0632\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641","match_names":["barbell one arm bent over row"],"muscle":"back","equipment":"barbell","aliases":["barbell one arm bent over row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.\nBend forward at the hips, keeping your back straight and your head in a neutral position.\nPull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\nLower the barbell back down to the starting position in a controlled manner.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0642\u0628\u0636\u0629 \u0627\u0644\u064a\u062f.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0631\u0623\u0633\u0643 \u0641\u064a \u0648\u0636\u0639 \u0645\u062d\u0627\u064a\u062f.\n\u0627\u0633\u062d\u0628 \u062