name_ar":"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629","match_names":["barbell one arm floor press"],"muscle":"triceps","equipment":"barbell","aliases":["barbell one arm floor press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on your back on the floor with your knees bent and feet flat on the ground.\nHold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.\nSlowly lower the barbell towards your chest, keeping your elbow close to your body.\nPause for a moment at the bottom, then push the barbell back up to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629\u060c \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0643\u0641 \u0627\u0644\u064a\u062f \u0645\u062a\u062c\u0647\u064b\u0627 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u0623\u0639\u0644\u0649 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u0628\u0627\u0631 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u0643 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\