\u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u0628\u0627\u0631 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0073","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["chest","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0073-i6LWjok.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0073-i6LWjok.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1e22bbc4-be1f-5c55-84c5-87d8a8de314c","source_id":"0022","name_en":"barbell pullover to press","name_ar":"\u0627\u0644\u0633\u062a\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f \u0644\u0644\u0636\u063a\u0637","match_names":["barbell pullover to press"],"muscle":"back","equipment":"barbell","aliases":["barbell pullover to press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on a bench with your head at one end and your feet on the ground.\nHold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.\nKeeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.\nPause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0631\u0623\u0633\u0643 \u0641\u064a \u0623\u062d\u062f \u0637\u0631\u0641\u064a\u0647 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0645\u0646\u0628\u0637\u062d\u0629 (\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0645\u062a\u062c\u0647\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643) \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062d\u062f\u064a\u062f \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0641\u064a \u062d\u0631\u0643\u0629 \u062a\u0634\u0628\u0647 \u0627\u0644\u0642\u0648\u0633 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0639\u0636\u0644\u0627\u062a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u0627\u0636\u063a\u0637 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643