1\u062a\u0641\u0627\u0639 \u0627\u0644\u0631\u0643\u0628\u0629.\n\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u062a\u0634\u064a\u0631 \u0625\u0644\u0649 \u0627\u0644\u062e\u0627\u0631\u062c \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u0646\u062d\u0646\u0649 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0644\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0633\u062d\u0628 \u0643\u062a\u0641\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0648\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646.\n\u0643\u0631\u0631