\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u062f\u064a\u062f \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0076","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0076-S9zHIvU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0076-S9zHIvU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"80e5378b-ce56-5163-8b98-060dba420cc3","source_id":"0078","name_en":"barbell rear lunge","name_ar":"\u0627\u0646\u062f\u0641\u0627\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u062e\u0644\u0641\u064a","match_names":["barbell rear lunge"],"muscle":"glutes","equipment":"barbell","aliases":["barbell rear lunge"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.\nTake a step backward with your right foot, landing on the ball of your foot.\nBend both knees to lower your body until your left thigh is parallel to the ground.\nPush through your left heel to return to the starting position.\nRepeat with the other leg.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0648\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0638\u0647\u0631\u0643.\n\u0627\u062a\u062e\u0630 \u062e\u0637\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0648\u0647\u0628\u0637 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u0643.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0644\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\