4a\u0643.\n\u0636\u0639 \u0645\u0642\u062f\u0645\u0629 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0645\u0631\u062a\u0641\u0639\u0629\u060c \u0645\u062b\u0644 \u0643\u062a\u0644\u0629 \u0623\u0648 \u062f\u0631\u062c\u0629.\n\u0636\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643 \u0648\u0623\u0645\u0633\u0643\u0647 \u0628\u0634\u0643\u0644 \u0622\u0645\u0646 \u0628\u064a\u062f\u064a\u0643.\n\u0623\u0628\u0642\u0650 \u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0648\u062c\u0630\u0639\u0643 \u0645\u0646\u0634\u063a\u0644\u064b\u0627\u060c \u0648\u0627\u0631\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0643\u0627\u062d\u0644\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0088","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0088-ktsFQAZ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce