 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0646\u062a\u0642\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u062e\u0641\u0636 \u0627\u0644\u062c\u0630\u0639 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0643\u0639\u0628\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0090","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0090-d960PgE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0090-d960PgE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3a1e6b43-2781-5ced-8c74-5a9fcb9eea0c","source_id":"0091","name_en":"barbell seated overhead press","name_ar":"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0627\u0644\u0639\u0644\u0648\u064a\u0629 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0627\u0644\u062c\u0627\u0644\u0633","match_names":["barbell seated overhead press"],"muscle":"shoulders","equipment":"barbell","aliases":["barbell seated overhead press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench with your back straight and feet flat on the ground.\nHold the barbell with an overhand grip, slightly wider than shoulder-width apart.\nLift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.\nPress the barbell overhead by extending your arms fully.\nPause for a moment at the top, then slowly lower the barbell back to shoulder level.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646 \u0627\u0644\u062d\u0627\u0645\u0644 \u0648\u0627\u0631\u0641\u0639\u0647 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641\u060c \u0645\u0639 \u062b\u0646\u064a \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0