 \u0648\u0648\u0631\u0643\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0099","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["glutes","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0099-gGNQmVt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0099-gGNQmVt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"18725f7f-05d4-5c79-8dd1-fa54f2af3bcc","source_id":"2799","name_en":"barbell sitted alternate leg raise","name_ar":"\u062c\u0644\u0633 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0639 \u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0628\u062f\u064a\u0644\u0629","match_names":["barbell sitted alternate leg raise"],"muscle":"core","equipment":"barbell","aliases":["barbell sitted alternate leg raise"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench with your back straight and hold a barbell across your thighs.\nKeeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.\nLower the raised leg back down and repeat with the other leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u0627\u0631\u0641\u0639\u064a \u0625\u062d\u062f\u0649 \u0633\u0627\u0642\u064a\u0643 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0645\u0645\u0643\u0646 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0645\u0631\u0641\u0648\u0639\u0629 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0643\u0631\u0631 \u0627\u0644\u0623\u0645\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2799","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2799-G7xoEzr.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2799-G7xoEzr.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
